<script setup lang="ts">
import zh from '../../../i18n/locales/zh-CN.json'
import en from '../../../i18n/locales/en-US.json'
import ja from '../../../i18n/locales/ja-JP.json'

const props=defineProps<{kind:'asn'|'dn';documentId:string|number}>()
const {t:uiT,locale:appLocale}=useI18n({useScope:'global'})
const languagePreference=useCookie<string|null>('wms_print_language',{maxAge:31536000,sameSite:'lax'})
const initialLanguage: 'zh'|'en'|'ja' = languagePreference.value==='zh'||languagePreference.value==='en'||languagePreference.value==='ja'?languagePreference.value:appLocale.value as 'zh'|'en'|'ja'
const {t,locale:printLanguage}=useI18n({useScope:'local',inheritLocale:false,locale:initialLanguage,messages:{zh,en,ja}})
watch(printLanguage,value=>{languagePreference.value=value})
const paperLanguage=computed(()=>printLanguage.value==='zh'?'zh-CN':printLanguage.value==='ja'?'ja-JP':'en')
const staff=useStaffStore(),{bizErrorMessage}=useBizError()
const record=ref<any>(null),loading=ref(true),error=ref('')
const number=computed(()=>props.kind.toUpperCase()+'-'+props.documentId)
const company=computed(()=>staff.staffInfo?.company as any)
const party=computed(()=>props.kind==='asn'?record.value?.supplier:({...record.value?.recipient,name:record.value?.ship_to?.name||record.value?.recipient?.name,phone:record.value?.ship_to?.phone||record.value?.recipient?.phone,zip_code:record.value?.ship_to?.postal_code||record.value?.recipient?.zip_code,address:record.value?.shipping_address||record.value?.recipient?.address}))
const quantities=computed(()=>props.kind==='asn'?['quantity','actual_quantity','sorted_quantity','damage_quantity']:['quantity','picked_quantity','packed_quantity','delivered_quantity'])
const quantityLabels=computed(()=>props.kind==='asn'?['expected','actual','sorted','damaged']:['expected','picked','packed','delivered'])
const total=(key:string)=>(record.value?.details||[]).reduce((sum:number,row:any)=>sum+Number(row[key]||0),0)
const print=()=>window.print()
onMounted(async()=>{record.value=await httpRequest<any>('/api/warehouse/'+props.kind+'/'+props.documentId,{onError:e=>error.value=bizErrorMessage(e)});loading.value=false})
useHead({title:()=>number.value+' · '+t('button.print-to-pdf')})
</script>
<template><div class="w-print-screen w-scope"><div class="toolbar"><NuxtLink :to="'/'+kind+'/detail/'+documentId">{{number}}</NuxtLink><label class="language-choice"><span>{{uiT('print-design.language')}}</span><select v-model="printLanguage"><option value="zh">中文</option><option value="en">English</option><option value="ja">日本語</option></select></label><WButton icon="printer" :disabled="loading||!record" @click="print">{{uiT('button.print-to-pdf')}}</WButton></div><WAlert v-if="error" tone="block" :title="error"/><WEmptyState v-if="loading" :title="t('common.status.loading')"/><div class="paper-scroll"><article v-if="record" class="paper" :lang="paperLanguage"><header><div class="company"><img v-if="company?.logo" :src="company.logo" :alt="company.name"/><strong v-else>{{company?.name}}</strong><span>{{company?.address}}</span><span>{{company?.phone}}<template v-if="company?.email"> · {{company.email}}</template></span></div><div class="document-title"><h1>{{kind==='asn'?'GOODS RECEIVED NOTE':'DELIVERY NOTE / PACKING LIST'}}</h1><span>{{t(kind+'.entity')}}</span><Barcode :value="number"/></div></header><div class="references"><div><small>{{t(kind+'.fields.number')}}</small><b>{{number}}</b></div><div><small>{{t(kind+'.fields.type')}}</small><b>{{t(kind+'.type.'+record[kind+'_type'])}}</b></div><div><small>{{t('common.fields.status')}}</small><b>{{t('common.status.'+String(record.status).replaceAll('_','-'))}}</b></div><div><small>{{t('common.dates.created')}}</small><b>{{$dayjs(record.created_at,'YYYY-MM-DD',record)}}</b></div></div><section class="parties"><div><h2>{{t('common.entities.warehouse')}}</h2><strong>{{record.warehouse?.name}}</strong><span>{{record.warehouse?.address}}</span><span>{{record.warehouse?.zip_code}}</span><span>{{record.warehouse?.phone}}</span></div><div><h2>{{t('common.entities.'+(kind==='asn'?'supplier':'recipient'))}}</h2><strong>{{party?.name}}</strong><span>{{party?.address}}</span><span>{{party?.zip_code}}</span><span>{{party?.phone}}</span></div><div><h2>{{t('common.entities.carrier')}}</h2><strong>{{record.carrier?.name}}</strong><span>{{t('common.fields.tracking-number')}}: {{record.tracking_number||'—'}}</span><span>{{record.carrier?.phone}}</span><span>{{t(kind==='asn'?'asn.fields.expected-arrival-date':'dn.fields.scheduled-date')}}: {{$dayjs(record[kind==='asn'?'expected_arrival_date':'expected_shipping_date'],'YYYY-MM-DD',record)}}</span></div></section><section v-if="kind==='asn'" class="arrival"><div><h2>{{t('print-design.arrival')}}</h2><span>{{record.received_at?$dayjs(record.received_at,'YYYY-MM-DD HH:mm',record):'____ – ____ – ____   ____ : ____'}}</span></div><div><h2>{{t('print-design.packages')}}</h2><span class="writing-line"/></div><div><h2>{{t('print-design.condition')}}</h2><span class="condition"><i/>{{t('print-design.good')}} <i/>{{t('print-design.damaged')}}</span></div></section><div v-if="record.remark" class="remarks"><b>{{t('common.fields.remark')}}</b><span>{{record.remark}}</span></div><div v-if="record.order_number" class="remarks"><b>{{t('dn.fields.order-no')}}</b><span>{{record.order_number}}</span></div><template v-if="kind==='dn'"><div v-if="record.packaging_info" class="remarks"><b>{{t('dn.fields.packing-info')}}</b><span>{{record.packaging_info}}</span></div><div v-if="record.special_handling" class="remarks"><b>{{t('dn.fields.special-handling')}}</b><span>{{record.special_handling}}</span></div></template><div class="lines-heading"><h2>{{kind==='asn'?'RECEIVING LINES':'PACKING LINES'}}</h2><span>{{record.details?.length||0}} LINES · {{total('quantity')}} PCS</span></div><table><thead><tr><th class="index">#</th><th>{{t('common.entities.goods')}}</th><th v-for="key in quantityLabels" :key="key" class="qty">{{t('common.quantities.'+key)}}</th><th class="notes">{{t('common.fields.remark')}}</th></tr></thead><tbody><tr v-for="(line,index) in record.details" :key="line.id"><td>{{Number(index)+1}}</td><td><b>{{line.goods?.name}}</b><span class="code">{{line.goods?.code}}</span><span v-if="line.weight||line.volume" class="code">{{t('common.units.weight')}}: {{line.weight??'—'}} kg · {{t('common.units.volume')}}: {{line.volume??'—'}} m³</span></td><td v-for="key in quantities" :key="key" class="qty">{{line[key]??'—'}}</td><td>{{line.remark}}</td></tr></tbody><tfoot><tr><td colspan="2">TOTAL</td><td v-for="key in quantities" :key="key" class="qty">{{total(key)}}</td><td/></tr></tfoot></table><div class="signatures"><div v-for="key in ['prepared','checked','received']" :key="key"><h2>{{t('print-design.'+key)}}</h2><div>{{t('common.fields.name')}}<i/></div><div>{{t('print-design.signature')}}<i/></div><div>{{t('print-design.date')}}<i/></div></div></div><footer><span>{{company?.name}}</span><b>{{number}}</b></footer></article></div></div></template>
<style scoped>
.w-print-screen{padding:24px;background:#E1E4EA;min-height:100vh;color:#151923;font-family:var(--w-font)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;max-width:794px;margin:0 auto 16px}.toolbar{flex-wrap:wrap}.language-choice{display:flex;align-items:center;gap:8px;margin-left:auto;font-size:13px}.language-choice select{height:36px;max-width:120px;padding:0 28px 0 10px;border:1px solid #CDD1DA;border-radius:6px;background:#fff;color:#151923}.paper:lang(ja){font-family:Inter,"Noto Sans JP",sans-serif}.toolbar>a{color:#5F1FE6;text-decoration:none;font-weight:600}.paper-scroll{overflow:auto}.paper{box-sizing:border-box;width:794px;min-height:1123px;padding:36px 44px 26px;margin:0 auto;background:#fff;font-size:10px;line-height:1.4;display:flex;flex-direction:column;font-variant-numeric:tabular-nums}.paper header{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;padding-bottom:12px}.company{display:flex;flex-direction:column;gap:2px;min-width:0}.company strong{font-size:14px;font-weight:800;margin-bottom:4px}.company>span{color:#4C5261}.company img{max-width:180px;max-height:52px;object-fit:contain;align-self:start}.document-title{display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex:none}.document-title h1{font-size:20px;font-weight:800;letter-spacing:.05em;line-height:1.2;margin:0}.document-title>span{font-size:10px;color:#4C5261;letter-spacing:.12em}.document-title :deep(svg){width:180px;height:52px}.references{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));border-top:2px solid #151923;border-bottom:1px solid #151923}.references>div{padding:6px 8px;display:flex;flex-direction:column;gap:1px}.references>div+div,.parties>div+div{border-left:1px solid #CDD1DA}small{font-size:8px;color:#4C5261}.parties{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-bottom:1px solid #151923}.parties>div{padding:7px 10px 9px;display:flex;flex-direction:column;gap:1px;overflow-wrap:anywhere}h2{font-size:9px;font-weight:700;line-height:14px;letter-spacing:.04em;margin:0 0 3px}.arrival{display:grid;grid-template-columns:1.25fr .9fr 1.55fr;border:1px solid #151923;margin-top:12px}.arrival>div{padding:6px 10px 7px;display:flex;flex-direction:column;gap:4px}.arrival>div+div{border-left:1px solid #CDD1DA}.writing-line{display:inline-block;width:56px;height:14px;border-bottom:1px solid #151923}.condition{display:flex;gap:5px;align-items:center}.condition i{width:11px;height:11px;border:1px solid #151923;display:inline-block;margin-left:4px}.remarks{display:flex;gap:8px;align-items:baseline;padding:7px 0 0}.lines-heading{display:flex;justify-content:space-between;align-items:baseline;margin:12px 0 4px}.lines-heading span{font-size:9px;color:#4C5261}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:9px;line-height:1.3}th{border-top:1.5px solid #151923;border-bottom:1px solid #151923;font-weight:600;padding:6px 4px;text-align:left}td{border-bottom:1px solid #CDD1DA;padding:7px 4px;vertical-align:top;overflow-wrap:anywhere}.index{width:24px}.qty{text-align:right;width:58px}.notes{width:100px}.code{display:block;font-size:8px;color:#4C5261;margin-top:2px}tfoot td{border-top:1px solid #151923;border-bottom:1.5px solid #151923;font-weight:700}.signatures{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;margin-top:auto;padding-top:32px}.signatures h2{padding-bottom:4px;border-bottom:1px solid #151923}.signatures>div>div{display:flex;gap:6px;align-items:end;margin-top:9px;font-size:8px;color:#4C5261}.signatures i{flex:1;min-height:14px;border-bottom:1px solid #151923}footer{display:flex;justify-content:space-between;border-top:1px solid #CDD1DA;padding-top:8px;margin-top:20px;font-size:8px;color:#4C5261}@media(max-width:820px){.w-print-screen{padding:16px}.paper{margin:0}}@media print{.w-print-screen{padding:0;background:#fff;min-height:0}.toolbar{display:none}.paper-scroll{overflow:visible}.paper{width:auto;min-height:265mm;padding:0;margin:0}thead{display:table-header-group}tr,.parties,.references,.signatures{break-inside:avoid}.signatures{margin-top:auto}tfoot{display:table-row-group}}
</style>
<style>@page{size:A4;margin:9.5mm 11.6mm 7mm;@bottom-right{content:counter(page) " / " counter(pages);font-family:Arial,sans-serif;font-size:8px;color:#656C7A}}@media print{html,body{background:#fff!important}.nuxt-devtools-panel,.nuxt-devtools-toggle{display:none!important}}</style>
